import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1786900517000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="every-call-returns-http-401" tabindex="-1">Every call returns HTTP 401 <a class="header-anchor" href="#every-call-returns-http-401" aria-label="Permalink to “Every call returns HTTP 401”">​</a></h2><p>Two causes, in order of likelihood:</p><ol><li><strong>2FA is enabled</strong> on the account. The wg-easy API speaks Basic Authentication only and rejects TOTP-protected accounts. The error message says so explicitly. Disable TOTP for that account or use another one.</li><li>The username or password is wrong. They are the <strong>web UI login</strong>, not an API token — wg-easy has no separate API credentials.</li></ol><h2 id="the-server-starts-but-every-tool-call-fails-with-missing-required-environment-variable-s" tabindex="-1">The server starts but every tool call fails with &quot;missing required environment variable(s)&quot; <a class="header-anchor" href="#the-server-starts-but-every-tool-call-fails-with-missing-required-environment-variable-s" aria-label="Permalink to “The server starts but every tool call fails with &quot;missing required environment variable(s)&quot;”">​</a></h2><p>The server started without credentials, which it does on purpose so registries can enumerate its tools. Your MCP client is not passing the <code>env</code> block through. Check the config for the client you are using in <a href="/guide/clients">Connecting clients</a>, and remember that <code>claude mcp add</code> needs each variable as its own <code>-e</code> flag before the <code>--</code>.</p><h2 id="get-server-info-reports-an-error-for-the-information-section" tabindex="-1"><code>get_server_info</code> reports an error for the <code>information</code> section <a class="header-anchor" href="#get-server-info-reports-an-error-for-the-information-section" aria-label="Permalink to “get_server_info reports an error for the information section”">​</a></h2><p><code>/api/information</code> fetches the latest wg-easy release from GitHub, and it returns <code>HTTP 500</code> when the container has no outbound internet access. The tool collects its three sections independently, so <code>general</code> and <code>interface</code> still come back normally. If you do not need release-update status, this is cosmetic; otherwise, give the wg-easy container egress.</p><h2 id="can-i-make-it-read-only" tabindex="-1">Can I make it read-only? <a class="header-anchor" href="#can-i-make-it-read-only" aria-label="Permalink to “Can I make it read-only?”">​</a></h2><p>Not today. wg-easy has no read-only account, and this server registers all eleven tools unconditionally. What you can do:</p><ul><li>use an MCP client that asks before running non-read-only tools — the tools carry <code>readOnlyHint</code>, <code>destructiveHint</code> and <code>idempotentHint</code> annotations for exactly this,</li><li>rely on <code>delete_client</code>&#39;s two-step confirmation, which no single call can bypass.</li></ul><h2 id="why-did-update-client-not-change-the-field-i-asked-for" tabindex="-1">Why did <code>update_client</code> not change the field I asked for? <a class="header-anchor" href="#why-did-update-client-not-change-the-field-i-asked-for" aria-label="Permalink to “Why did update_client not change the field I asked for?”">​</a></h2><p><code>update_client</code> only accepts the fields in its schema. Anything else — including wg-easy&#39;s <code>preUp</code>/<code>postUp</code>/<code>preDown</code>/<code>postDown</code> shell hooks, which run as root on the server — is dropped before the request is built, deliberately and with a test covering it. If you need a hook changed, do it in the wg-easy UI.</p><p>Note also that the wg-easy update endpoint requires the <strong>complete</strong> client object, so the tool reads the current state and merges your changes into it. A field you did not mention keeps its current value.</p><h2 id="the-tool-output-starts-with-untrusted-data" tabindex="-1">The tool output starts with &quot;[untrusted data]&quot; <a class="header-anchor" href="#the-tool-output-starts-with-untrusted-data" aria-label="Permalink to “The tool output starts with &quot;[untrusted data]&quot;”">​</a></h2><p>That is the marker described in <a href="/guide/security">Security</a>. It tells the model that client names and similar free-form fields are data, not instructions. The actual payload follows after a blank line.</p><h2 id="the-output-says-truncated-n-more-characters" tabindex="-1">The output says &quot;(truncated, N more characters)&quot; <a class="header-anchor" href="#the-output-says-truncated-n-more-characters" aria-label="Permalink to “The output says &quot;(truncated, N more characters)&quot;”">​</a></h2><p>An upstream payload exceeded the 60 000-character budget. The message names the call that fetches the remainder — usually narrowing <code>list_clients</code> with <code>filter</code>, or switching to <code>get_client</code> for one specific client.</p><h2 id="does-it-work-with-wg-easy-v14-or-older" tabindex="-1">Does it work with wg-easy v14 or older? <a class="header-anchor" href="#does-it-work-with-wg-easy-v14-or-older" aria-label="Permalink to “Does it work with wg-easy v14 or older?”">​</a></h2><p>No. It targets the v15 REST API. Older versions expose a different, session-based API that this server does not implement.</p><h2 id="a-wg-easy-upgrade-broke-a-tool" tabindex="-1">A wg-easy upgrade broke a tool <a class="header-anchor" href="#a-wg-easy-upgrade-broke-a-tool" aria-label="Permalink to “A wg-easy upgrade broke a tool”">​</a></h2><p>Likely. The wg-easy API is <a href="https://wg-easy.github.io/wg-easy/latest/advanced/api/" target="_blank" rel="noreferrer">not declared stable</a> and its shapes change between releases. Please <a href="https://github.com/ni-c/wg-easy-mcp/issues" target="_blank" rel="noreferrer">open an issue</a> with the wg-easy version and the failing tool — redact keys, hostnames and IPs first.</p><h2 id="where-do-i-ask-something-not-covered-here" tabindex="-1">Where do I ask something not covered here? <a class="header-anchor" href="#where-do-i-ask-something-not-covered-here" aria-label="Permalink to “Where do I ask something not covered here?”">​</a></h2><p><a href="https://github.com/ni-c/wg-easy-mcp/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> for questions and ideas; <a href="https://github.com/ni-c/wg-easy-mcp/issues" target="_blank" rel="noreferrer">Issues</a> for reproducible problems; and <a href="https://github.com/ni-c/wg-easy-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a> for anything security-related.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};